ausing it to display an \"unknown error\" message instead of the trip plan.","tree":{"sha":"2d582646d5bd62a3c57c376f85b20517fd9f9a9c","url":"https://api.github.com/repos/berkyalkn/AI-travel-agent/git/trees/2d582646d5bd62a3c57c376f85b20517fd9f9a9c"},"url":"https://api.github.com/repos/berkyalkn/AI-travel-agent/git/commits/0d9d879a4191348908672c2195b1cbe32735e0e1","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/151683817?v=4","events_url":"https://api.github.com/users/berkyalkn/events{/privacy}","followers_url":"https://api.github.com/users/berkyalkn/followers","following_url":"https://api.github.com/users/berkyalkn/following{/other_user}","gists_url":"https://api.github.com/users/berkyalkn/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/berkyalkn","id":151683817,"login":"berkyalkn","node_id":"U_kgDOCQqC6Q","organizations_url":"https://api.github.com/users/berkyalkn/orgs","received_events_url":"https://api.github.com/users/berkyalkn/received_events","repos_url":"https://api.github.com/users/berkyalkn/repos","site_admin":false,"starred_url":"https://api.github.com/users/berkyalkn/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/berkyalkn/subscriptions","type":"User","url":"https://api.github.com/users/berkyalkn","user_view_type":"public"},"html_url":"https://github.com/berkyalkn/AI-travel-agent/commit/0d9d879a4191348908672c2195b1cbe32735e0e1","node_id":"C_kwDOPTOlxtoAKDBkOWQ4NzlhNDE5MTM0ODkwODY3MmMyMTk1YjFjYmUzMjczNWUwZTE","parents":[{"html_url":"https://github.com/berkyalkn/AI-travel-agent/commit/baf6b45095eb8cd66e1124da274cde408f54d14d","sha":"baf6b45095eb8cd66e1124da274cde408f54d14d","url":"https://api.github.com/repos/berkyalkn/AI-travel-agent/commits/baf6b45095eb8cd66e1124da274cde408f54d14d"}],"sha":"0d9d879a4191348908672c2195b1cbe32735e0e1","url":"https://api.github.com/repos/berkyalkn/AI-travel-age